import{_ as t,H as i,f as a,i as l}from"./chunks/framework.BH2BK_3i.js";const g=JSON.parse('{"title":"02 | 具身智能：OpenAI真正的野心是什么？","description":"","frontmatter":{},"headers":[{"level":2,"title":"ChatGPT 的发展简史","slug":"chatgpt-的发展简史","link":"#chatgpt-的发展简史","children":[]},{"level":2,"title":"猩球崛起（使用工具）","slug":"猩球崛起-使用工具","link":"#猩球崛起-使用工具","children":[]},{"level":2,"title":"西部世界（自我思考）","slug":"西部世界-自我思考","link":"#西部世界-自我思考","children":[]},{"level":2,"title":"技术要点","slug":"技术要点","link":"#技术要点","children":[{"level":3,"title":"任务规划（Planning）","slug":"任务规划-planning","link":"#任务规划-planning","children":[]},{"level":3,"title":"记忆唤醒（Memory）","slug":"记忆唤醒-memory","link":"#记忆唤醒-memory","children":[]},{"level":3,"title":"驾驭工具（Tools）","slug":"驾驭工具-tools","link":"#驾驭工具-tools","children":[]}]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"AI大模型系统实战/02｜具身智能：OpenAI真正的野心是什么？.md","filePath":"AI大模型系统实战/02｜具身智能：OpenAI真正的野心是什么？.md","lastUpdated":1795452834000}'),n={name:"AI大模型系统实战/02｜具身智能：OpenAI真正的野心是什么？.md"};function p(s,e,o,r,E,h){return i(),a("div",null,[...e[0]||(e[0]=[l('<h1 id="_02-具身智能-openai真正的野心是什么" tabindex="-1">02 | 具身智能：OpenAI真正的野心是什么？ <a class="header-anchor" href="#_02-具身智能-openai真正的野心是什么" aria-label="Permalink to &quot;02 | 具身智能：OpenAI真正的野心是什么？&quot;">​</a></h1><p>你好，我是 Tyler。</p><p>说起 ChatGPT，你对它的印象是什么呢？</p><p>据我观察，不同人有不同的看法。有些人不太高兴，因为担心它的代码能力会对工程师的工作造成威胁。另一些人的态度是不屑一顾，认为它只会说些不切实际的东西。还有一些人正在学习一些易上手、但欠缺深度的教程，用它建立知识库，自动化日常工作，觉得“小小 GPT 不过如此”，很容易就能“拿捏”它了。</p><p>不过，这一轮技术革命并不是冲着这“仨瓜俩枣”来的，未来所有数字化工作都可能被大模型技术颠覆。所以今天我会带你正本清源，看看这一轮技术革命的真正“终局”是什么样子。</p><p>好大的口气，你可能会这么想。的确，在一个技术快速发展的阶段下断言，确实有些“冒险”，但我非常有信心与你分享我的判断，因为这已几乎成为了全球大模型工作者的共识。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/02/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/02/1.png" alt=""></a></p><ul><li>大语言模型驱动的智能体</li></ul><p>如上图所示，我们未来所面临的终局形态，不只是一个能说会道的聊天机器人，而是“具身智能”的通用人工智能。所谓具身智能，就是像人一样能与环境交互感知，自主规划、决策、行动的机器人。</p><h2 id="chatgpt-的发展简史" tabindex="-1">ChatGPT 的发展简史 <a class="header-anchor" href="#chatgpt-的发展简史" aria-label="Permalink to &quot;ChatGPT 的发展简史&quot;">​</a></h2><p>像人一样？你可能有点半信半疑，但别以为这是科幻小说虚构的故事。如果你足够细心，完全可以在 OpenAI 的发展过程中发现一些端倪。我现在就带你回顾一下 GPT 发展的过程当中有哪些重要历史节点，看看它是怎样一步步进化的。</p><p>GPT 的诞生要归功于 NLP 的快速发展。从 2018 年到 2021 年，是第一代大语言模型（LLM）的“技术爆炸”期。人们逐渐学会了，如何使用海量的无标签数据，来训练这些“涌现”智能的大模型。随后，OpenAI 采用强化学习技术，点亮了 LLM 的智能，ChatGPT 由此横空出世。</p><p>如果你对前面的故事已经非常熟悉了，那说明你已超过 95% 侃侃而谈大模型技术的人了。</p><p>但实际上，真正的故事才刚刚开始。我画了一张 OpenAI 产品发展的示意图，你可以猜测一下他们之间的关系，接下来，我将会为你道出其中的逻辑。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/02/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/02/2.png" alt=""></a></p><ul><li>OpenAI 产品发展过程</li></ul><h2 id="猩球崛起-使用工具" tabindex="-1">猩球崛起（使用工具） <a class="header-anchor" href="#猩球崛起-使用工具" aria-label="Permalink to &quot;猩球崛起（使用工具）&quot;">​</a></h2><p>人类之所以在地球上显得独特，一个重要原因是我们更擅长使用工具。对于已经掌握语言能力的大型语言模型（LLM）来说，学会使用工具只是一个时间问题，而且它们的学习速度比我们想象的还要快。</p><p>从 OpenAI 产品的各种迹象来看，他们正在教导 LLM 使用甚至创造工具。</p><p>首先，OpenAI 推出了插件和联网功能，弥补了大型语言模型自身记忆的不足。这标志着 LLM正式开始学习使用工具。</p><p>随后推出的函数功能，意味着 LLM 已经学会使用 API 来完成复杂任务，在此之前这可是后端工程师的主要工作。最后推出的代码编辑器，让 LLM 直接学会制造工具，这几乎动摇了所有工程师的饭碗。</p><p>虽然人类可以掌控使用工具的大模型，但令人既兴奋又担心的是，研究人员还找到了让 LLM“思考”的方法。我们这就来看看这人造的思维能力是怎样的！</p><h2 id="西部世界-自我思考" tabindex="-1">西部世界（自我思考） <a class="header-anchor" href="#西部世界-自我思考" aria-label="Permalink to &quot;西部世界（自我思考）&quot;">​</a></h2><p>在美剧《西部世界》中，机器人乐园的创始人偷偷地为机器人植入了“意识”代码，导致机器人自我对话，从而产生了自我意识。在真实世界中，类似的事情正在发生。各大机构正在制造能够自我对话的“智能体”，从而彻底解放人类的脑力工作。</p><p>你可以回想一下，当人类面临一个任务的时候，会怎么做？</p><p>首先，我们会思考任务的主要步骤有哪些，然后调取相关的资料，形成可行的方案，接着通过分工去执行具体的事项，最后汇总完成任务。对于智能体来说也是一样，只不过要将之前人类大脑的工作交给大语言模型（LLM）完成。</p><h2 id="技术要点" tabindex="-1">技术要点 <a class="header-anchor" href="#技术要点" aria-label="Permalink to &quot;技术要点&quot;">​</a></h2><p>在这里，我为你准备了一张智能体的结构图。为了让智能体具备“自治”的能力，一般需要将计划、记忆和工具这三部分组合起来。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/02/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/02/3.png" alt=""></a></p><ul><li>大语言模型驱动的智能体</li></ul><p>接下来，我们就沿着这三个部分看看有哪些重点工作，当你把它们背后的逻辑弄清楚之后，后面课程里学习具体细节时，才能做到心中有数。</p><h3 id="任务规划-planning" tabindex="-1">任务规划（Planning） <a class="header-anchor" href="#任务规划-planning" aria-label="Permalink to &quot;任务规划（Planning）&quot;">​</a></h3><p>教大型语言模型（LLM）思考的过程，有点像苏格拉底的“产婆术”。苏格拉底认为，他不能代替别人思考，但他可以通过提问引导别人思考，就好像产婆引导孕妇一样。</p><p>这种方法可以让 LLM 对自己的想法进行调整和反思，最经典的方法是 ReAct，他有三个概念：</p><ul><li><p>Thought：表示让大语言模型思考，目前需要做哪些行为，行为的对象是谁，它要采取的行为是不是合理的。</p></li><li><p>Act：也就是针对目标对象，执行具体的动作，比如调用 API 这样的动作，然后收集环境反馈的信息。</p></li><li><p>Obs：它代表把外界观察的反馈信息，同步给大语言模型，协助它做出进一步的分析或者决策。</p></li></ul><p>你可以看看文稿后面的这张截图，图里展示的是 ReAct 的一个示例，它可以帮你加深理解。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/02/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/02/4.png" alt=""></a></p><ul><li>ReAct 问答示例</li></ul><p>我们可以用这种方法来启发 LLM 工作，比如让它帮你制定工作方案，并持续向它提问，例如：你的执行步骤有哪些潜在隐患和风险、有哪些方法可以降低风险、能否帮助我制定一些安全风险预案等等问题，以确保它生成的内容安全可靠。</p><p>在这个过程中，你要尽量唤醒 LLM 的相关知识，生成合理的计划，此时思维链技术（CoT）就非常重要了，它可以让 LLM 将任务分解为可解释的步骤。更多关于这些技术的细节，我们将在第三、第四章展开讨论。在此阶段，你只需掌握 LLM 在任务规划里如何使用即可。</p><h3 id="记忆唤醒-memory" tabindex="-1">记忆唤醒（Memory） <a class="header-anchor" href="#记忆唤醒-memory" aria-label="Permalink to &quot;记忆唤醒（Memory）&quot;">​</a></h3><p>无论是在制定计划、使用工具或执行任务的过程中，LLM 都需要外部信息的帮助来辅助进行思考。为了更好地让 LLM 拥有记忆力，我们不妨先参考一下人类是如何记忆的。</p><p>在神经科学研究中，人类的记忆可分为感觉记忆、短期记忆和长期记忆三种类型。</p><ul><li><p>感觉记忆，是人体接收到外部信号以后，瞬间保留的视觉、听觉、触觉的记忆片段，在 AI系统中类似于高维嵌入表示，也就是我们常说的 “Embedding”。</p></li><li><p>短期记忆，是你当前意识中的信息，在 LLM 中类似于提示词（Prompt）中的所有信息。</p></li><li><p>长期记忆，包含了你能回忆的所有信息，在 LLM 中类似于外部向量存储。</p></li></ul><p>LLM 能“消化”的，只有提示词（Prompt）中的短时记忆，所以你只需要在长期记忆中选择最重要的内容放入提示词，这里我给出一张图方便你理解这个过程。</p><ul><li><p>首先，LLM 在得到任务后，会帮助你制定记忆唤醒方案。</p></li><li><p>然后，AI 系统执行该方案，生成相关的查询指令，从外部数据中查询数据。</p></li><li><p>最后，我们将这些数据交给 LLM 来判断是否已获得足够完成任务的数据。如果没有，LLM会生成新的唤醒方案，并循环这个过程。</p></li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/02/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/02/5.png" alt=""></a></p><p>现在，LLM 不但能制定任务规划，还能调取外部知识了。仅这两个能力足以让它自动化地完成很多脑力工作了。如果再让它学会使用工具，那潜力简直不可限量。我们再来聊一聊 LLM使用工具的方法。</p><h3 id="驾驭工具-tools" tabindex="-1">驾驭工具（Tools） <a class="header-anchor" href="#驾驭工具-tools" aria-label="Permalink to &quot;驾驭工具（Tools）&quot;">​</a></h3><p>要让 LLM 学会使用工具，首先需要让它认识工具，比如 TALM、Toolformer 和 Gorilla 等方法让 LLM 学会理解 API 的调用注释，这是 Plugin 和 Function 等功能的基础。</p><p>下图展示了 Gorilla 教会 LLM 使用 API 的全过程。</p><ul><li><p>首先，我们使用大量 API 调用代码和文档作为语料，训练一个可以理解 API 的大语言模型。</p></li><li><p>然后，AI 系统还将对这些 API 进行向量化操作，将它们存储在向量数据库中作为外部记忆。</p></li><li><p>随后，当用户发起请求时候，AI 系统会从外部记忆中，获取跟请求相关的 API 交给 LLM。</p></li><li><p>最后，LLM 组合串联这些 API 形成代码，并执行代码，完成 API 的调用，生成执行结果。</p></li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/02/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/02/6.png" alt=""></a></p><ul><li>Gorilla 算法核心步骤</li></ul><p>此外，根据 Google 的线报，GPT-4 使用了 MoE（混合专家模型）技术，由十多个领域专家模型共同提供服务。所以，它需要上层 LLM 有能力为指定的需求，找到最合适的专家模块，这其实也是一种 LLM 使用工具的能力。同样，就像前面提到的，OpenAI 发布的 CodeInterpreter，也正式宣告 LLM 制作工具的时代已经来临。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>相信通过今天的学习，你已经知道了这一轮技术革命的目的是什么，而且不仅 OpenAI 在进行这些工作，国内的各大科技公司也在积极探索。这节课的知识重点，你可以参考后面的导图来回顾。</p><p>我们通过“产婆术”让大型语言模型学会“思考”。我们让它学会制定和反思自己的计划，并教会它获取外部知识和使用工具的方法，让它可以独立完成复杂任务。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/02/7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/02/7.png" alt=""></a></p><p>而且，LLM 除了使用工具之外，已经可以制造工具了。OpenAI 推出的 Code Interpreter，让LLM 有能力解决处理几乎各种模态的二进制数据，而不仅限于文字和图像。长远来看，这将颠覆现有软件工程的模式，Serverless 已经不新鲜了，Codeless 才是未来的常态。</p><p>除此之外，还有很多重要的内容，比如大模型的分布式训练技术、多模态大模型的训练方法，以及实现可信 AI，解决大模型幻觉的办法等等。其实这些相关技术，早在既有的 AI 系统中得到了很好的实践，这些内容也会在后续的课程中逐渐展开，敬请期待。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>结合今天的内容，你觉得教会 LLM 制定计划，反思计划以及使用工具这几个方面，哪方面的训练难度更大？为什么？</p><p>恭喜你完成我们第 2 次打卡学习，期待你在留言区和我交流互动。也欢迎你把这节课分享给身边朋友，和 TA 一起学习进步。</p>',64)])])}const u=t(n,[["render",p]]);export{g as __pageData,u as default};
